          var Parameters = "e=" + frmForgetEmail;            MakePostRequest(base_path + 'member/processforgetpwd', Parameters, 'json', forgetPasswordRes);            return false;        }    }    function forgetPasswordRes(data) {        if(data.errcode == '404') {            fnCallSessionExpire();            return false;        } else if(data.errcode==-1) {            $('#ErrfrmForgetEmail').text(data.msg);            return false;        } else if(data.errcode == 1) {            $('#msg').text(data.msg);            fnRedirectPageTimeOut(base_path+'member');        }    }</script></body></html>